  'settings.connections.typeHint': '“Không” và “Trực tiếp” không phải cùng một dòng. Không là bất động: nó không chỉ tới kết nối nào và không bao giờ được dùng, nên chỉ tồn tại cho tới khi bạn điền xong. Trực tiếp là một lựa chọn thật - đi ra bằng đường của chính máy này và cố ý bỏ qua mọi proxy cho những máy chủ nêu bên dưới, đó là cách để một NAS nằm ngoài proxy áp cho cả ứng dụng. Dòng có bộ lọc khớp với máy chủ thắng dòng không có bộ lọc, nên dòng trực tiếp có bộ lọc luôn thắng một proxy vơ hết.',
