  'settings.rules.folderFromSettingsHint': 'Không quy tắc nào chỉ định thư mục, nên liên kết sẽ rơi vào thư mục tải về đã cấu hình - có thể nằm trong thư mục con theo gói, nếu thiết lập đó đang bật. Trang này sẽ không đoán đường dẫn đầy đủ giúp bạn: điều chắc chắn nó nói được là không quy tắc nào đã đổi nó.',
  'settings.rules.alsoSets': 'Còn đặt',

  'settings.reconnect.method': 'Cách làm',
  'settings.reconnect.setupTitle': 'Thiết lập',
  'settings.reconnect.methodHint': 'Cách báo cho router thả đường truyền rồi quay lại với một địa chỉ mới. “Lệnh” chạy một chương trình, “Yêu cầu” phát lại một cuộc trao đổi HTTP đã ghi, UPnP hỏi thẳng gateway qua mạng mà không cần đăng nhập gì cả, còn “Kịch bản” giao một tệp cho trình thông dịch. Chỉ những ô mà cách đã chọn cần đến mới hiện ra; các ô còn lại vẫn giữ nguyên nội dung bạn gõ và quay lại khi bạn chuyển sang chúng.',
  'settings.reconnect.method.none': 'Tắt',
  'settings.reconnect.method.command': 'Lệnh',
  'settings.reconnect.method.http': 'Yêu cầu',
  'settings.reconnect.method.upnp': 'UPnP',
  'settings.reconnect.method.script': 'Kịch bản',
  'settings.reconnect.offState': 'Kết nối lại đang tắt. Không có gì đòi router cấp địa chỉ mới, và giới hạn của máy chủ được để yên cho khoảng chờ thử lại thông thường.',

  'settings.reconnect.command': 'Chương trình',
  'settings.reconnect.commandHint': 'Đường dẫn đầy đủ tới chương trình sẽ chạy. Nó được khởi động thẳng chứ không qua shell, nên một ống dẫn, một chuyển hướng hay hai lệnh liền nhau thuộc về cách “Kịch bản”. %%router%%, %%username%%, %%password%% và %%ip%% được điền vào trước khi chạy.',
  'settings.reconnect.args': 'Tham số',
  'settings.reconnect.argsHint': 'Mỗi dòng một tham số, để tham số có khoảng trắng vẫn là một tham số. Cũng bốn biến đó được điền vào ở đây.',

  'settings.reconnect.upnpState': 'Không cần gì thêm. Gateway được tìm bằng cách hỏi mạng, và chính điều đó khiến đây là cách chạy được mà không cần biết gì về router.',
  'settings.reconnect.upnpLocation': 'URL mô tả của gateway',
  'settings.reconnect.upnpLocationHint': 'Tùy chọn, và thường để trống. Chỉ điền ở nơi tìm kiếm multicast bị lọc trong khi bản thân gateway vẫn tới được ngon lành, đó là điều mà riêng việc dò tìm không bao giờ chữa nổi.',

  'settings.reconnect.interpreter': 'Trình thông dịch',
  'settings.reconnect.interpreterHint': 'Chương trình được giao kịch bản, kèm đường dẫn đầy đủ: /bin/sh, /bin/bash, /usr/bin/python3.',
  'settings.reconnect.interpreterArgs': 'Tham số của trình thông dịch',
  'settings.reconnect.interpreterArgsHint': 'Mỗi dòng một tham số, đặt trước tệp kịch bản. Thường để trống.',
  'settings.reconnect.script': 'Kịch bản',
  'settings.reconnect.scriptHint': 'Nội dung được ghi ra một tệp tạm riêng tư, và trình thông dịch chỉ nhận đường dẫn của tệp đó, nên không có gì ở đây phải nằm trong dấu nháy trên một dòng lệnh. Các biến được điền trước khi tệp được ghi, nghĩa là mật khẩu bạn gõ vào ô này cũng lọt vào tệp ấy: dùng %%password%% thì nó ở lại trong ô mật khẩu.',

  'settings.reconnect.router': 'Địa chỉ router',
  'settings.reconnect.routerHint': 'Router trong mạng của chính bạn, không kèm giao thức: 192.168.1.1, chứ không phải http://192.168.1.1/. %%router%% bung ra thành cái đó. Đây không phải địa chỉ công khai, và hai thứ này không bao giờ được nhầm lẫn: một yêu cầu đăng nhập nhắm vào địa chỉ công khai sẽ gửi mật khẩu router của bạn ra Internet.',
  'settings.reconnect.routerFind': 'Tìm router của tôi',
  'settings.reconnect.routerFinding': 'Đang tìm…',
  'settings.reconnect.routerFound': 'Đã tìm thấy {address}.',
  'settings.reconnect.routerFoundVia': 'Đã tìm thấy {address} qua {iface}. Nên xem lại: trong container đây thường là cầu nối chứ không phải router.',
  'settings.reconnect.routerFailed': 'Không đọc được địa chỉ router nào ở đây: {reason}',
  'settings.reconnect.username': 'Tên đăng nhập router',
  'settings.reconnect.usernameHint': 'Tài khoản đăng nhập router, không phải tài khoản ở máy chủ tải. %%username%% bung ra thành cái đó.',
  'settings.reconnect.password': 'Mật khẩu router',
  'settings.reconnect.passwordStored': 'đã lưu, và không bao giờ gửi ngược lại đây',
  'settings.reconnect.passwordHint': 'Mật khẩu đã lưu không bao giờ được gửi ngược về trang này, vì thế ô mới trống: cứ để trống thì mật khẩu đã lưu vẫn giữ nguyên. Gõ mật khẩu mới để thay. Muốn bỏ hẳn thì gõ gì đó rồi xóa trắng ô lần nữa.',

  'settings.reconnect.requests': 'Yêu cầu',
  'settings.reconnect.requestsHint': 'Được phát lại theo thứ tự, và lượt chạy dừng ở yêu cầu đầu tiên mà router không trả lời. Đây chính là cách LiveHeader của JDownloader: thường là một lần đăng nhập, rồi khởi động lại hoặc ngắt kết nối. Ô nào cũng nhận biến.',
  'settings.reconnect.requestsEmpty': 'Chưa có yêu cầu nào. Thêm một cái, hoặc dán một kịch bản đã ghi.',
  'settings.reconnect.requestAdd': 'Thêm một yêu cầu',
  'settings.reconnect.requestStep': 'Bước {n}',
  'settings.reconnect.requestUp': 'Đưa yêu cầu này lên',
  'settings.reconnect.requestDown': 'Đưa yêu cầu này xuống',
  'settings.reconnect.requestRemove': 'Xóa yêu cầu này',
  'settings.reconnect.requestMethod': 'Phương thức',
  'settings.reconnect.requestUrl': 'URL',
  'settings.reconnect.requestUrlHint': 'Toàn bộ URL, kể cả giao thức. http://%%router%%/login.cgi là dạng thường gặp.',
  'settings.reconnect.requestHeaders': 'Tiêu đề',
  'settings.reconnect.requestHeadersHint': 'Mỗi dòng một cái, dạng Tên: giá trị. Tiêu đề Host được tôn trọng và thật sự đi ra đường truyền, đúng thứ mà firmware router phục vụ trang quản trị theo máy chủ ảo cần đến.',
  'settings.reconnect.requestBody': 'Thân',
  'settings.reconnect.requestBodyHint': 'Gửi nguyên như đang có. Một phần thân không có kiểu nội dung riêng sẽ đi như một lần gửi biểu mẫu, mà một lần đăng nhập router đã ghi lại thì đúng là như vậy.',

  'settings.reconnect.import': 'Nhập một kịch bản',
  'settings.reconnect.importLabel': 'Kịch bản LiveHeader hoặc curl',
  'settings.reconnect.importHint': 'Dán một kịch bản kết nối lại của JDownloader vào đây, kèm cả các dấu mốc. Biến của nó được dịch ngay khi nhập, và %%%routerip%%% trở thành địa chỉ router chứ không phải địa chỉ công khai, vì ở đây hai thứ đó khác nhau.',
  'settings.reconnect.importRead': 'Đọc kịch bản',
  'settings.reconnect.importReading': 'Đang đọc…',
  'settings.reconnect.importClose': 'Đóng',
