  'settings.reconnect.importRefusedCount': '{n} bị từ chối',
  'settings.reconnect.importUse': 'Thay danh sách bằng {n}',
  'settings.reconnect.importLine': 'Dòng {n}',
  'settings.reconnect.importBlocked': 'Không lấy gì từ một kịch bản có dòng bị từ chối. Nửa kịch bản router là một lần đăng nhập mà không khởi động lại, và chuyện đó chỉ lộ ra sau nhiều ngày, dưới dạng một địa chỉ không bao giờ đổi.',
  'settings.reconnect.importFailed': 'Không đọc được kịch bản: {reason}',

  'settings.reconnect.checkTitle': 'Kiểm tra địa chỉ',
  'settings.reconnect.checkUrl': 'URL kiểm tra IP',
  'settings.reconnect.checkUrlHint': 'Được lấy trước khi cách đã chọn chạy và lấy lại lần nữa sau đó; lượt chạy coi như xong ngay khi địa chỉ hiện ra ở đó đã đổi. Cố tình không có giá trị mặc định: một trình quản lý tải tự bạn dựng lên không nên bắt đầu báo địa chỉ của bạn cho một dịch vụ bạn chưa từng chọn. Thứ hiện ra phải là địa chỉ mà Internet nhìn thấy, vì một trang trả về địa chỉ trong mạng nhà bạn thì không phân biệt nổi một lần kết nối lại với chuyện chẳng có gì xảy ra.',
  'settings.reconnect.checkPresets': 'Dịch vụ quen thuộc',
  'settings.reconnect.checkPresetsHint': 'Một lối tắt cho ai không có sở thích riêng, không phải mặc định: không cái nào được chọn thay bạn, và bất cứ trang nào in ra địa chỉ công khai của bạn cũng làm được việc đó.',
  'settings.reconnect.interval': 'Số giây giữa hai lần kiểm tra (1 đến 60)',
  'settings.reconnect.intervalHint': 'Chờ bao lâu giữa hai lần ngó vào URL kiểm tra, sau khi cách đã chọn chạy xong. Có mức sàn, vì một vòng lặp không có mức sàn sẽ biến dịch vụ kiểm tra thành cái bia.',
  'settings.reconnect.timeout': 'Số giây tiếp tục kiểm tra (5 đến 900)',
  'settings.reconnect.timeoutHint': 'Còn ngó bao lâu nữa trước khi coi lượt chạy là thất bại. Một lần kết nối lại mà mười lăm phút sau vẫn còn chờ thì đã hỏng rồi, bất kể ở đây ghi bao nhiêu. Thời gian chờ nhỏ hơn khoảng cách giữa hai lần kiểm tra sẽ được nâng lên bằng nó, nếu không lượt chạy đã kết thúc trước cả lần kiểm tra đầu tiên.',
  'settings.reconnect.clamped': 'Đã lưu thành {n}.',

  'settings.reconnect.runTitle': 'Chạy một lần ngay bây giờ',
  'settings.reconnect.run': 'Chạy ngay',
  'settings.reconnect.running': 'Đang chạy…',
  'settings.reconnect.runMoved': 'Địa chỉ đã đổi từ {from} sang {to}.',
  'settings.reconnect.runDetail': '{n} lần kiểm tra, {secs} giây',
  'settings.reconnect.runBusy': 'Đã có một lần kết nối lại đang chạy, nên lần này không khởi động. Kết quả thuộc về người đã yêu cầu lần đầu.',
  'settings.reconnect.runFailed': 'Lần kết nối lại không đi tới cùng: {reason}',
