  'settings.reconnect.stateBusy': 'Đang chạy',
  'settings.reconnect.stateUnreadable': 'Không đọc được trạng thái kết nối lại. Máy chủ có tới được không?',
  'settings.reconnect.notReady': 'Chưa sẵn sàng: {reason}',
  'settings.reconnect.reason.off': 'Kết nối lại đang tắt',
  'settings.reconnect.reason.noCommand': 'Phương thức lệnh chưa có chương trình để chạy',
  'settings.reconnect.reason.noRequests': 'Phương thức yêu cầu chưa có yêu cầu nào',
  'settings.reconnect.reason.requestNoURL': 'Yêu cầu {n} không có URL',
  'settings.reconnect.reason.noInterpreter': 'Phương thức tập lệnh chưa có trình thông dịch để chạy nó',
  'settings.reconnect.reason.noScript': 'Phương thức tập lệnh chưa có tập lệnh',
  'settings.reconnect.reason.noCheckURL': 'Chưa có URL kiểm tra IP',
  'settings.reconnect.reason.unknownMethod': 'Phương thức không xác định “{method}”',
  'settings.reconnect.reason.noRouter': 'Tập lệnh dùng %%{var}%% nhưng chưa đặt địa chỉ bộ định tuyến',
  'settings.reconnect.runUsesSaved': 'Chạy theo cấu hình đã lưu, không phải cấu hình trên màn hình. Hãy lưu trước.',
  'settings.reconnect.policy': 'Khi nào việc này tự xảy ra',
  'settings.reconnect.policyHint': 'Kết nối lại tự động chỉ được kích hoạt ở một chỗ, và trang này không phải chỗ đó. Một lần bắt đầu khi chính backend tải tự xin thử lại sau một khoảng chờ, đó là cách một máy chủ nói rằng giới hạn gắn với địa chỉ này. Nó không bao giờ chạy khi hàng đợi đang dừng, vì khởi động lại router sẽ làm đứt những lượt tải còn đang chạy. Nó không bao giờ chạy khi phần kết nối lại chưa được cấu hình đầy đủ. Mỗi lúc chỉ chạy một: yêu cầu thứ hai chờ phán quyết của yêu cầu đầu thay vì tranh router với nó. Còn nếu địa chỉ không đổi thì không có gì được đẩy lên sớm, cứ để khoảng chờ thử lại thông thường chạy hết.',

  'shell.bar': 'Hàng đợi và thanh trạng thái',
  'shell.scope': 'Đang điều khiển',
  'shell.scopeHint': 'Trang bên dưới đang hiện thực thể bạn này, nên thanh cũng nhắm vào đó. Một thực thể bạn giữ hàng đợi riêng và giới hạn tốc độ riêng, nên những gì thực thể này không chuyển tiếp được sẽ hiện là không dùng được thay vì áp lên máy này.',

  'task.moveUp': 'Chuyển lên',
  'task.moveDown': 'Chuyển xuống',
  'menu.priority': 'Độ ưu tiên',
  'menu.move': 'Di chuyển',
  'menu.forceStart': 'Buộc lên đầu hàng đợi',
  'menu.queueStopped': 'Hàng đợi đã dừng',
  'pkg.queueOrder': 'Chuyển cả gói',

  'priority.highest': 'Cao nhất',
  'priority.higher': 'Cao hơn',
  'priority.high': 'Cao',
  'priority.default': 'Mặc định',
  'priority.low': 'Thấp',
  'priority.lower': 'Thấp hơn',
  'priority.lowest': 'Thấp nhất',

  'settings.chunks': 'Số kết nối cho mỗi lượt tải (0 = tự động)',
  'settings.chunksHint': 'Một lượt tải mở bao nhiêu kết nối khi không có gì cụ thể hơn áp dụng. Một quy tắc, hoặc một lượt tải riêng lẻ, có thể nêu con số của mình và thắng con số này. Máy chủ chịu được ít hơn thì vẫn nhận ít hơn: giới hạn của máy chủ chỉ có thể hạ con số xuống, không bao giờ nâng lên. Với 0 thì ứng dụng tự quyết. Quá vài kết nối chẳng được gì trên máy chủ giới hạn theo từng tệp, và là cách chắc chắn để một tài khoản bị đánh dấu.',
  'task.chunks': 'Kết nối (0 = thiết lập chung)',
  'task.chunksHint': 'Riêng lượt tải này mở bao nhiêu kết nối. Nó thắng thiết lập chung và mọi quy tắc đã đặt, nhưng không bao giờ thắng máy chủ: máy chủ chịu được ít hơn thì vẫn nhận ít hơn. Với 0 thì ngoại lệ bị gỡ và con số được quyết ở nơi khác trở lại.',
  'columns.connection': 'Kết nối',

  'props.title': 'Thuộc tính',
  'props.mixed': 'Nhiều giá trị',
  'props.mixedHint': 'Các hàng này không khớp nhau nên ô để trống. Không đụng vào thì không đổi gì; gõ vào đó thì mọi hàng đã chọn nhận đúng những gì bạn gõ.',
  'props.name': 'Tên',
  'props.nameHint': 'Một tên tệp, không bao giờ là đường dẫn: bất cứ thứ gì viết ra thư mục đều bị cắt còn một cái tên. Lượt tải đã xong cũng được đổi tên trên đĩa, nên danh sách và thư mục không thể lệch nhau. Lượt đang chạy giữ nguyên tệp mà backend của nó đang mở và nhận tên mới khi xong. Lượt chưa bắt đầu nhận ngay. Một cái tên thuộc về một tệp, nên ô này chỉ hiện khi chọn đúng một hàng.',
  'props.comment': 'Ghi chú',
  'props.commentHint': 'Ghi chú của riêng bạn về liên kết này. Nó được lưu và hiển thị trong danh sách; không phần nào của ứng dụng hành động theo nó.',
  'props.priority': 'Độ ưu tiên',
