  'intake.clipboardWatchUnavailable': 'Không dùng được ở đây: trình duyệt chỉ cho một trang đọc bảng nhớ tạm qua HTTPS hoặc trên localhost. Ctrl+V bên trong KnightLoader vẫn hoạt động.',
