  'settings.access.relay.title': 'Bộ tiếp sức của dự án',
  'settings.access.relay.body': 'Relay là bên trung gian giúp mọi phiên bản của bạn truy cập được từ ngoài mạng nhà, tức là từ bất cứ đâu. Relay này do dự án cung cấp miễn phí.',
  'settings.access.relay.use': 'Dùng bộ tiếp sức của dự án',
  'settings.access.relay.leadProject': 'Chạy được ngay, không cần cài đặt gì. Mọi thứ các thực thể của bạn nói với nhau đều được mã hóa, và chỉ bạn giữ khóa.',
  'settings.access.relay.address': 'Địa chỉ',
  'settings.access.relay.seesButton': 'Nó thấy được gì?',
  'settings.access.relay.seesTip': 'Bộ tiếp sức không thấy: liên kết, lượt tải, tệp và mã truy cập của bạn.\n\nBộ tiếp sức thấy: địa chỉ IP của các phiên bản của bạn và thời điểm chúng gửi gì đó.\n\nĐiều này không thể mã hóa cho khuất đi. Nếu bạn thấy phiền, hãy chạy bộ tiếp sức của riêng mình.',
  'settings.access.relay.none': 'Không có bộ tiếp sức',
  'settings.access.relay.noneHint': 'Không có relay nào hoạt động. Trong cùng một mạng, tức mạng nhà bạn, các phiên bản vẫn tự tìm thấy nhau. Qua các mạng khác nhau thì không, nên không có truy cập từ xa.',
  'settings.access.relay.own': 'Bộ tiếp sức riêng',
  'settings.access.relay.project': 'Bộ tiếp sức của dự án',
  'settings.access.relay.whichHint': 'Đi qua {address}',
  'settings.access.relay.savedProject': 'Bộ tiếp sức của dự án đang bật',
  'settings.access.relay.savedOwn': 'Bộ tiếp sức của bạn đang bật',
  'settings.access.relay.savedOff': 'Đã tắt bộ tiếp sức',
  'settings.access.ownRelay.title': 'Bộ tiếp sức của riêng bạn',
  'settings.access.ownRelay.body': 'Chạy relay của riêng bạn thay cho relay của dự án.',
  'settings.access.ownRelay.use': 'Dùng bộ tiếp sức của tôi',
  'settings.access.ownRelay.lead': 'Hai cách: thực thể này làm bộ tiếp sức, hoặc bạn nhập một địa chỉ.',
  'settings.access.ownRelay.serveLabel': 'Dùng phiên bản này làm relay',
  'settings.access.ownRelay.serveHint': 'Chỉ hoạt động khi phiên bản này truy cập được từ bên ngoài, ví dụ qua Nginx Proxy Manager và tên miền riêng của bạn.',
  'settings.access.ownRelay.serveClients': 'Hiện có {count} kết nối.',
  'settings.access.ownRelay.addressLabel': 'Địa chỉ',
  'settings.access.ownRelay.addressPlaceholder': 'ví dụ https://relay.mydomain.tld',
  'settings.access.ownRelay.save': 'Lưu',
  'settings.access.ownRelay.everyInstance': 'Địa chỉ này chỉ áp dụng cho thực thể này. Hãy nhập nó ở mọi thực thể.',
  'settings.access.ownRelay.containerLabel': 'Là vùng chứa riêng',
  'settings.access.ownRelay.containerHint': 'Nếu không phiên bản nào của bạn truy cập được từ bên ngoài, relay phải đặt ở nơi khác: trên máy chủ của bạn hoặc một VPS nhỏ. Cài container từ Unraid Community Applications, hoặc bằng lệnh bên dưới.\n\nContainer không cần thiết lập: chạy nó, nhập địa chỉ ở trên, xong. Nó không lưu gì cả nên cũng không có gì để sao lưu.',
  'settings.access.tokens.title': 'Token API',
  'settings.access.tokens.intro':
    'Thông tin xác thực có tên cho một tập lệnh, tiện ích mở rộng trình duyệt hoặc điện thoại. Mỗi cái có thể được thu hồi riêng, mà không cần đổi mật khẩu chung mà mọi máy khách khác sử dụng.',
  'settings.access.tokens.empty': 'Chưa có token nào được cấp.',
  'settings.access.tokens.new': 'Token mới',
