  'settings.access.tokens.neverUsed': 'chưa bao giờ',
  'settings.access.tokens.revoke': 'Thu hồi',
  'settings.access.tokens.secretTitle': 'Sao chép token này ngay bây giờ',
  'settings.access.tokens.secretWarning':
    'Đây là lần duy nhất token này được hiển thị. Nó được lưu dưới dạng hash một chiều trên thực thể này, vì vậy nếu bị mất sẽ không có cách nào đọc lại được, chỉ có thể thu hồi nó và tạo một cái mới.',
  'settings.access.tokens.copy': 'Sao chép',
  'settings.access.tokens.copied': 'Đã sao chép',
  'settings.access.tokens.done': 'Xong',
  'settings.access.tokens.howToUse': 'Gửi nó dưới dạng tiêu đề: Authorization: Bearer <token>',
  'settings.access.tokens.createFailed': 'Không thể tạo token: {error}',
  'settings.access.identity.title': 'Danh tính của phiên bản này',
  'settings.access.identity.nameLabel': 'Tên',
  'settings.access.identity.namePlaceholder': 'ví dụ: Máy chủ tại nhà',
  'settings.access.identity.nameHint': 'Được đề xuất đầu tiên khi ghép nối và trong mã QR bên dưới, thay vì tên mà hệ điều hành hoặc môi trường chạy container tình cờ đặt cho máy này. Tùy chọn - để trống để tiếp tục dùng tên đó.',
  'settings.access.identity.domainsLabel': 'Miền đã biết',
  'settings.access.identity.domainsHint': 'Tự động ghi nhớ ngay khi có yêu cầu thực sự đến qua đó, nên nó vẫn được liệt kê ở đây kể cả khi các yêu cầu sau đến qua IP mạng LAN thay vào đó. Thêm một mục thủ công cho miền đã được cấu hình nhưng chưa từng được truy cập qua - mỗi dòng một địa chỉ đầy đủ, ví dụ https://kl.example.com.',
  'settings.access.cardTitle': 'Kết nối các phiên bản và truy cập từ xa',
  'settings.access.phrase.body': 'Một cụm từ kết nối mọi KnightLoader bạn đang chạy. Tạo tại đây, rồi dán vào các phiên bản khác - không tài khoản, không đăng nhập, không cần cấu hình gì.',
  'settings.access.phrase.noPasswordWarning': 'Phiên bản này chưa có mật khẩu. Cụm từ này chạm tới mọi phiên bản bạn kết nối bằng nó, nên ai đọc được ở đây sẽ tới được tất cả, không chỉ phiên bản này. Tốt hơn hãy đặt mật khẩu ở trên trước.',
  'settings.access.phrase.activate': 'Tạo cụm từ',
  'settings.access.phrase.howLead': 'Mười hai từ, chỉ vậy thôi. Đây là việc cần làm, và điều gì diễn ra:',
  'settings.access.phrase.howStep1': 'Trên phiên bản này, bấm "{button}". Mười hai từ hiện ra.',
  'settings.access.phrase.howStep2': 'Mở KnightLoader trên máy kia, vào đúng trang này, bấm "{button}" rồi gõ mười hai từ vào.',
  'settings.access.phrase.howStep3': 'Xong! Mỗi phiên bản giờ xuất hiện ở phiên bản kia trong mục „Phiên bản“, và bạn điều khiển máy nào từ máy nào cũng được. Khi bật bộ tiếp sức, các phiên bản của bạn tiếp cận được từ ngoài mạng.',
  'settings.access.phrase.howWhat': 'Các từ là một bí mật, không phải địa chỉ. Mỗi phiên bản tính ra hai khóa từ đó: một để tìm những phiên bản khác, một để mã hóa.\n\nĐể tìm nhau, mỗi phiên bản tự gọi đến cùng một điểm hẹn trên internet. Ai trình cùng một khóa thì được nối với nhau. Vì thế không phiên bản nào của bạn cần truy cập được từ bên ngoài.\n\nĐiểm hẹn không đọc được gì. Nó không bao giờ thấy các từ của bạn, và mọi thứ đi qua nó đều được mã hóa bằng khóa thứ hai.',
  'settings.access.phrase.statusDisconnected': 'Chưa kết nối',
  'settings.access.phrase.statusHintProject': 'Đã kết nối tới relay của dự án. Truy cập từ xa đã sẵn sàng.',
  'settings.access.phrase.statusHintOwn': 'Đã kết nối tới relay của bạn. Truy cập từ xa đã sẵn sàng.',
  'settings.access.phrase.statusHintOff': 'Không có relay nào hoạt động. Chỉ có thể truy cập các phiên bản trong mạng nội bộ.',
  'settings.access.phrase.statusHintLost': 'Không liên lạc được với relay. KnightLoader vẫn đang thử lại. Trong lúc đó các phiên bản chỉ gặp nhau trong mạng nội bộ.',
  'settings.access.phrase.statusConnected': 'Đã kết nối',
  'settings.access.phrase.howButton': 'Cái này hoạt động thế nào?',
  'settings.access.phrase.joinButton': 'Nhập cụm từ',
  'settings.access.phrase.joinPlaceholder': 'Dán mười hai từ từ phiên bản khác của bạn',
  'settings.access.phrase.joinConfirm': 'Kết nối',
  'settings.access.phrase.errChecksum': 'Cụm từ này không hợp lệ - kiểm tra xem có từ nào gõ sai hoặc đảo chỗ không.',
  'settings.access.phrase.errUnknownWord': 'Từ thứ {position} ("{word}") không nằm trong các từ được chấp nhận.',
  'settings.access.phrase.errWordCount': 'Đây là {count} từ - một cụm từ cần {need}.',
  'settings.access.phrase.yourPhrase': 'Cụm từ kết nối của bạn',
  'settings.access.phrase.pasteHint': 'Dán mười hai từ này vào mọi phiên bản khác mà bạn muốn kết nối.',
  'settings.access.phrase.qrHint': 'Hoặc quét mã này từ thiết bị kia thay vì gõ tay.',
  'settings.access.phrase.revealWhy': 'Nhập mật khẩu của phiên bản này để hiện lại cụm từ. Nó mở mọi phiên bản trong nhóm, không chỉ phiên bản này.',
  'settings.access.phrase.revealConfirm': 'Hiện',
  'settings.access.phrase.showAgain': 'Hiện cụm từ',
