  'settings.browsertools.install': 'Cài đặt',
  'settings.browsertools.installIOS':
    'Trên iPhone hoặc iPad: mở trang này trong Safari, chạm vào Chia sẻ, sau đó chạm «Thêm vào Màn hình chính».',
  'settings.access.intakePortsHint': 'Các cách khác để truy cập trực tiếp vào phiên bản này, ngoài đăng nhập thông thường - mỗi cách hiển thị khả năng truy cập riêng tại đây.',
  'settings.nav.browsertools': 'Trình duyệt và ứng dụng',
  'settings.browsertools.bookmarkletStep1': 'Kéo nút bên dưới vào thanh dấu trang của trình duyệt - nó được lưu như bất kỳ dấu trang nào khác, không cài đặt gì cả.',
  'settings.browsertools.bookmarkletStep2': 'Trên bất kỳ trang nào, nhấp vào nó (chọn một số văn bản trước nếu bạn chỉ muốn phần đó). Một tab KnightLoader nhỏ mở ra với liên kết của trang đó, hoặc văn bản đã chọn, đã được điền sẵn - xem lại và thêm nó từ đó dưới dạng lượt tải xuống.',
  'settings.browsertools.installLabel': 'Cách cài đặt',
  'settings.browsertools.apkLabel': 'Tải APK',
  'settings.browsertools.installChromiumStep1': 'Giải nén tệp đã tải xuống.',
  'settings.browsertools.installChromiumStep2': 'Mở chrome://extensions (hoặc edge://extensions, brave://extensions).',
  'settings.browsertools.installChromiumStep3': 'Bật Chế độ nhà phát triển.',
  'settings.browsertools.installChromiumStep4': 'Chọn “Load unpacked” rồi chọn thư mục đã giải nén.',
  'settings.browsertools.installChromiumStep5': 'Nhấp vào biểu tượng mảnh ghép cạnh thanh địa chỉ và ghim KnightLoader. Chrome không tự đưa tiện ích mới lên thanh công cụ.',
  'settings.browsertools.installFirefoxStep1': 'Để cài đặt vĩnh viễn: mở about:addons và nhấp vào biểu tượng bánh răng ở góc trên bên phải.',
  'settings.browsertools.installFirefoxStep2': 'Chọn “Install Add-on From File…” rồi chọn tệp này.',
  'settings.browsertools.installFirefoxStep3': 'Để dùng thử nhanh, hãy mở about:debugging#/runtime/this-firefox và chọn “Load Temporary Add-on” - biến mất khi Firefox khởi động lại.',
  'settings.browsertools.bookmarkletTitle': 'Bookmarklet',
