  'settings.resolvers.moduleUnavailableHint': 'Mọi thứ bên dưới vẫn được lưu và có hiệu lực ngay khi yt-dlp khả dụng - chỉnh sửa ngay bây giờ không làm mất gì cả.',
  'settings.resolvers.intro': 'Cấu hình cho backend yt-dlp, nơi lấy các trang media và streaming mà chính yt-dlp hỗ trợ. Dịch vụ nào xử lý một liên kết nhất định - yt-dlp, tài khoản debrid, hay sidecar JD không giao diện - được quyết định bởi thứ tự định tuyến trên trang Tài khoản; ở đây chỉ nói về những gì yt-dlp làm sau khi một liên kết đã được định tuyến tới nó.',
  'settings.resolvers.quality': 'Chất lượng',
  'settings.resolvers.qualityHint': 'Bộ chọn -f nào được dùng khi khởi chạy yt-dlp. "Tốt nhất có thể" là giá trị mặc định của chính yt-dlp, và là giá trị mọi lượt tải trước đây đã dùng trước khi có cài đặt này.',
