  'settings.torrents.uploadLimitUnit': 'KiB/s',
  'settings.torrents.portTitle': 'Cổng và ánh xạ',
  'settings.torrents.port': 'Cổng',
  'settings.torrents.portHint': 'Cổng mà thực thể này lắng nghe kết nối từ bầy. 0 để công cụ torrent tự chọn.',
  'settings.torrents.portMapHint': 'Yêu cầu router chuyển tiếp cổng ở trên đến máy này qua UPnP, để các peer sau một router khác vẫn có thể tiếp cận nó. Không phải router nào cũng hỗ trợ điều này, và một số chấp nhận yêu cầu mà không thực sự hoạt động.',
  'settings.torrents.portMapButton': 'Thử ánh xạ UPnP',
  'settings.torrents.portMapping': 'Đang hỏi router…',
  'settings.torrents.portMapNeedsPort': 'Đặt một cổng ở trên trước khi ánh xạ nó - với 0, router không có gì để chuyển tiếp đến.',
  'settings.torrents.portMapConfirmed': 'Đã xác nhận: cổng {port} đã được ánh xạ và đã xác minh là có thể truy cập.',
  'settings.torrents.portMapUnconfirmed': 'Router đã chấp nhận yêu cầu, nhưng không thể xác nhận việc ánh xạ thực sự hoạt động. Một số router làm điều này một cách âm thầm - hãy thử kiểm tra kết nối từ bên ngoài mạng.',
  'settings.torrents.portMapFailed': 'Không thể ánh xạ cổng: {error}',
  'settings.torrents.portMapUnavailable': 'Bản dựng này chưa hỗ trợ ánh xạ cổng.',
  'settings.torrents.networkTitle': 'Khám phá peer',
  'settings.torrents.dht': 'DHT',
  'settings.torrents.dhtHint': 'Tìm peer mà không cần tracker, bằng cách dùng các client BitTorrent khác làm danh mục phân tán.',
  'settings.torrents.pex': 'Trao đổi peer (PEX)',
  'settings.torrents.pexHint': 'Trao đổi các peer đã biết với những peer đã kết nối, để bầy có ít peer được tìm thấy nhanh hơn.',
  'settings.torrents.privateNote': 'Một torrent riêng tư tự động tắt cả hai ngay khi biết được siêu dữ liệu của nó, bất kể thiết lập ở đây - ngay lập tức đối với một tệp .torrent đã tải lên, hoặc ngay khi siêu dữ liệu riêng của một liên kết magnet đến từ bầy. Hầu hết các tracker riêng tư cấm các tài khoản dùng bất kỳ tính năng nào trong hai tính năng đó.',
  'settings.torrents.engineNote': 'Tỷ lệ seed mục tiêu, thời lượng seed mục tiêu và cổng giờ đây thực sự có tác dụng với mọi torrent mà công cụ này khởi chạy - tuy nhiên cổng chỉ áp dụng cho torrent đầu tiên kể từ lần khởi động lại gần nhất của thực thể này, vì client torrent riêng của công cụ chỉ được tạo một lần duy nhất và không bao giờ được tạo lại sau đó; một lần lưu sau đó vẫn được lưu đúng và có hiệu lực kể từ lần khởi động lại tiếp theo. Giới hạn tải lên vẫn chỉ được lưu và xác thực, công cụ hiện chưa có cách nào áp dụng nó vào một lượt tải đang diễn ra. DHT và PEX bên dưới cũng ở tình trạng tương tự đối với một torrent thông thường (không riêng tư): giá trị mặc định riêng của thực thể này cũng chưa có tác dụng với một lượt tải đang diễn ra, nên torrent vẫn tiếp tục seed với cả hai được bật bất kể thiết lập ở đây - torrent riêng tư là một trường hợp hoàn toàn khác, xem thêm ghi chú bên dưới. Dù vậy, nút ánh xạ bên dưới vẫn làm một điều thực sự: nó yêu cầu router một cách trung thực chuyển tiếp số cổng đã nhập ở trên, dù có torrent nào đang lắng nghe ở đó hay không.',
