  'onboarding.finish': 'Bắt đầu dùng KnightLoader',
  'onboarding.welcome.title': 'Chào mừng đến với KnightLoader',
  'onboarding.welcome.body': 'KnightLoader là trình quản lý tải xuống tự lưu trữ: dán hoặc thả một liên kết, và nó sẽ được lấy bởi backend thực sự xử lý nó - engine tích hợp sẵn cho các liên kết tệp thông thường, yt-dlp cho các trang media, dịch vụ debrid cho các hoster bạn đã trả tiền, hoặc JDownloader không giao diện cho mọi thứ còn lại. Chuyến tham quan ngắn này bao gồm cài đặt duy nhất đáng để kiểm tra trước khi bạn bắt đầu.',
  'onboarding.welcome.langLabel': 'Ngôn ngữ giao diện',
  'onboarding.folder.title': 'Tệp nên được lưu ở đâu?',
  'onboarding.folder.body': 'Đây là thư mục mà các bản tải xuống đã hoàn tất được ghi vào. Nhập một đường dẫn hoặc duyệt máy chủ để chọn một thư mục - bạn có thể thay đổi lại bất cứ lúc nào từ trang cài đặt Chung.',
  'onboarding.accounts.title': 'Hoster cao cấp, bất cứ khi nào bạn muốn',
  'onboarding.accounts.body': 'Hàng đợi hoạt động hoàn toàn không cần tài khoản. Khi bạn muốn tốc độ tối đa trên một hoster hoặc dịch vụ debrid mà bạn đã trả tiền, hãy thêm thông tin đăng nhập của nó vào mục Tài khoản - hiện tại không có gì cần thiết lập ở đây.',
  'onboarding.accounts.link': 'Mở Tài khoản',
  'onboarding.finished.title': 'Bạn đã sẵn sàng',
  'onboarding.finished.body': 'Vậy là hết chuyến tham quan. Trang Trợ giúp trong Cài đặt có hướng dẫn đầy đủ về mọi thứ khác mà phiên bản này làm được, và hầu hết các điều khiển đều có giải thích riêng phía sau biểu tượng (i).',

