  'settings.nav.shortcuts': 'Phím tắt',
  'settings.shortcuts.subtitle': 'Mọi lệnh đi kèm phím tắt mặc định, được nhóm theo nơi áp dụng. Thay đổi một liên kết phím, hoặc đặt lại về mặc định.',
