  'settings.feeds.lastPolledHint': 'Lần gần nhất đăng ký này được ngó tới, bất kể lần ngó đó có thành công hay không. Nó bị quên đi khi máy chủ khởi động lại, còn những gì đăng ký đã thêm vào thì không, nên một feed bạn theo dõi suốt nhiều tháng vẫn đọc ra là chưa kiểm tra trong vài giây sau lần khởi động lại.',
