  'settings.feeds.seededNo': 'Lần kiểm tra đầu tiên vẫn còn ở phía trước, và cho tới khi nó chạy thì không có gì được thêm vào',
  'settings.feeds.seededHint': 'Lần kiểm tra đầu tiên của một đăng ký mới ghi lại mọi thứ feed đang mang lúc đó và không thêm gì trong số đó, để bạn không bị đổ nguyên kho cũ của một nơi phát hành vào trong một lượt. Chỉ những gì xuất hiện sau đó mới được thêm vào.',
  'settings.feeds.remembered': 'Đã nhớ {n} mục',
  'settings.feeds.rememberedHint': 'Đăng ký này nhận ra lại được bao nhiêu mục, để chúng không được thêm lần thứ hai trong lúc feed vẫn còn đưa chúng ra. Nhiều nhất 500 mục cho mỗi đăng ký; những mục cũ nhất rơi ra trước, và một mục còn nằm trong feed thì không bao giờ nằm trong số đó.',
  'settings.feeds.test': 'Thử',
  'settings.feeds.testBusy': 'Đang lấy về',
  'settings.feeds.testHint': 'Lấy địa chỉ này về đúng một lần và cho bạn xem trong đó có gì, để bạn thấy các tiêu đề mà bộ lọc của bạn được đối chiếu với. Nó chỉ đọc: không có gì rơi vào bộ thu thập và không có gì được ghi là đã thấy, nên bạn bấm được cả với một địa chỉ chưa lưu.',
