  'settings.feeds.testEmpty': 'Địa chỉ đã trả lời, nhưng tài liệu hoàn toàn không mang mục nào. Hãy kiểm tra xem nó có thật sự là một feed hay chỉ là trang mà feed nằm trên đó.',
  'settings.feeds.testFailed': 'Không đọc được feed này',
