  'settings.headerProfiles.title': 'Hồ sơ header',
  'settings.headerProfiles.hint': 'Một số trang chỉ giao tệp cho một trình duyệt đã đăng nhập, hoặc chỉ khi lời gọi đến từ chính một trang của họ. Một hồ sơ lưu các header cho đúng một trang, được niêm phong y như thông tin đăng nhập của bạn, và KnightLoader gửi kèm chúng trong mọi lượt tải từ trang đó.',
  'settings.headerProfiles.empty': 'Chưa có hồ sơ header nào.',
  'settings.headerProfiles.emptyHint': 'Một hồ sơ đáng có ngay khi một lượt tải chỉ chạy được lúc bạn đang đăng nhập trong trình duyệt.',
  'settings.headerProfiles.add': 'Thêm hồ sơ',
  'settings.headerProfiles.name': 'Tên hồ sơ',
  'settings.headerProfiles.nameHint': 'Cái tên bạn dùng để gọi hồ sơ này, trong một quy tắc Packagizer cũng như ở đây. Chỉ chữ cái, chữ số và - _ hoặc .',
  'settings.headerProfiles.namePlaceholder': 'ví dụ forum',
  'settings.headerProfiles.origin': 'Trang',
  'settings.headerProfiles.originHint': 'Hãy dán địa chỉ của trang mà bạn đã sao chép các header từ đó. Một cổng khác, và http thay vì https, được tính là một trang khác và cần hồ sơ riêng. Một tên miền phụ không được hồ sơ của tên miền chính bao phủ.',
  'settings.headerProfiles.headers': 'Header',
  'settings.headerProfiles.headerName': 'Tên',
  'settings.headerProfiles.headerValue': 'Giá trị',
  'settings.headerProfiles.valueStored': 'Đã lưu',
  'settings.headerProfiles.valueStoredHint': 'Giá trị nằm lại trên thực thể này và không bao giờ được gửi ngược về trang này. Cứ để nguyên ô này để giữ nó, hoặc gõ một giá trị mới để thay thế.',
  'settings.headerProfiles.addHeader': 'Thêm header',
  'settings.headerProfiles.removeHeader': 'Gỡ header này',
