  'settings.rules.action.category': 'Danh mục',
  'settings.rules.action.categoryHint': 'Xếp các liên kết khớp vào một trong các ngăn kéo từ trang Danh mục, ngăn kéo đó mang theo thư mục riêng, chỗ riêng trong hàng đợi, công tắc giải nén riêng và quy tắc xung đột riêng của nó. Để nguyên thì không quy tắc nào có ý kiến gì và liên kết vẫn chưa được xếp vào đâu. Nếu quy tắc này còn nêu cả một thư mục tải về thì thư mục đó thắng, và ngăn kéo vẫn góp mọi thứ còn lại. Nêu tên một ngăn kéo đã bị xóa sẽ bị từ chối lúc bạn lưu, vì một quy tắc trỏ tới một ngăn kéo không còn ở đó thì với mọi liên kết nó khớp, nó hoàn toàn không làm gì cả, mà không nói một lời nào.',
  'settings.rules.action.categoryNone': 'Chưa có danh mục nào. Hãy tạo một danh mục trên trang Danh mục trước, nếu không quy tắc này sẽ xếp liên kết vào một ngăn kéo không tồn tại.',
  'settings.rules.action.categoryMissing': '{id} (đã xóa)',

  'settings.resolvers.cookieJars': 'Tệp đã lưu',
  'settings.resolvers.cookieJarsHint': 'Một tệp đã lưu không bao giờ được hiện lại: nó là một phiên đăng nhập đang sống, nên nó chỉ đi theo một chiều, vào trong máy chủ này. Muốn thay thế thì bạn cứ dán tệp mới đè lên.',
  'settings.resolvers.cookieHost': 'Trang',
  'settings.resolvers.cookieHostPlaceholder': 'youtube.com, hoặc địa chỉ mà bạn đã xuất tệp ra từ đó',
