  'task.retry.skipDetail': 'Khởi động liên kết ngay lập tức thay vì đợi hết khoảng chờ. Bộ đếm vẫn chạy tiếp: đây chính là lần thử lại vốn đã được lên lịch, không phải một lần thêm.',
  'task.retry.skipFailed': 'Không khởi động được lần thử lại.',
  'volume.rangeLabel': 'Khoảng thời gian',
